const proposalAsset=name=>name+'?v='+RELEASE;
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),clone=x=>JSON.parse(JSON.stringify(x));
const periods={once:{name:'One-time',months:0},month:{name:'Monthly',months:1},quarter:{name:'Quarterly',months:3},year:{name:'Annually',months:12}};
let templates=[],state=null,step=0,clientChoices=[],dirty=false,lastGenerated='',logoData='';
const titleCase=value=>String(value||'').trim().replace(/\b[\p{L}][\p{L}\p{N}’-]*/gu,word=>['UAE','IFZA','DMCC','SPC','FTA','VAT','IFRS','CT','IT','ERP','AML','USD','AED','UK','DIFC','ADGM','LLC','FZCO','CFO','INZO'].includes(word.toUpperCase())?word.toUpperCase():word[0].toUpperCase()+word.slice(1).toLowerCase());
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Dubai'});
const money=(n,c)=>c+' '+(n/100).toLocaleString('en-AE',{minimumFractionDigits:2,maximumFractionDigits:2});
function dateLabel(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return value||'Not specified';const d=new Date(value+'T12:00:00Z');return isNaN(d)?value:d.toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Dubai'});}
function feeCalculation(row){
 if(row.optional&&!row.selected)return {excluded:true,net:0,vat:0,total:0,billNet:0,billVat:0,billTotal:0};
 if(row.included)return {net:0,vat:0,total:0,billNet:0,billVat:0,billTotal:0,included:true};
 const amount=Number(row.amount),qty=Number(row.quantity),vat=Number(row.vat),basis=periods[row.basis],billing=periods[row.billing];
 if(String(row.amount??'').trim()===''||!Number.isFinite(amount)||amount<0||!Number.isFinite(qty)||qty<=0||qty>100000||amount>100000000||![0,5].includes(vat)||!basis||!billing)return {error:'Enter a valid fee, quantity and VAT rate.'};
 if((basis.months===0)!==(billing.months===0)||basis.months>billing.months)return {error:'Choose a collection period at least as long as the fee basis.'};
 const net=Math.round(Math.round(amount*100)*qty),tax=Math.round(net*vat/100),factor=basis.months?billing.months/basis.months:1,billNet=Math.round(net*factor),billVat=Math.round(billNet*vat/100);
 if(!Number.isSafeInteger(billNet+billVat))return {error:'The fee total is too large.'};
 return {net,vat:tax,total:net+tax,billNet,billVat,billTotal:billNet+billVat,factor};
}
function optionTotals(option){const groups={};let missing=0;for(const row of activeRows(option)){const c=feeCalculation(row);if(c.error){missing++;continue;}if(row.included||c.excluded)continue;const key=row.billing;groups[key]??={net:0,vat:0,total:0};groups[key].net+=c.billNet;groups[key].vat+=c.billVat;groups[key].total+=c.billTotal;}return {groups,missing};}
const jurisdictions=['IFZA','DMCC','Meydan','Sharjah Publishing City (SPC)','Ajman Free Zone','RAKEZ','SHAMS','Dubai Mainland','Abu Dhabi Mainland','Other'];
const activitySuggestions=['Management consultancy','Business consultancy','IT consultancy','Software development','Marketing services','E-commerce','General trading'];
const commonFees=['Licence and incorporation','Professional fees','Establishment card','Visa / residency processing','Labour file / processing','E-sign card','Tenancy contract provision','Special trade name','Additional licensed activity','Bank account application assistance','Accounting services','External Audit Report','Corporate tax registration / filing','VAT registration / returns'];
const family=()=>templates.find(t=>t.id===state?.templateId)?.family||'other';
const recipientName=()=>family()==='formation'?state.formationClientName:state.clientName;
const recipientContact=()=>family()==='formation'?state.formationClientName:(state.contact||state.clientName);
