document.addEventListener('input',e=>{const el=e.target;if(el.dataset.field){state[el.dataset.field]=el.type==='checkbox'?el.checked:el.value;if(el.dataset.field==='reference')state.autoReferenceNumber='';if(el.dataset.field==='date'&&state.autoReferenceNumber&&el.value){state.reference=formatReference(state.autoReferenceNumber,el.value);const ref=document.querySelector('[data-field="reference"]');if(ref)ref.value=state.reference;}changed();}else if(el.dataset.option!==undefined&&el.dataset.key){const o=state.options[Number(el.dataset.option)],target=el.dataset.row!==undefined?o.rows[Number(el.dataset.row)]:o;target[el.dataset.key]=el.type==='checkbox'?el.checked:el.value;if(el.dataset.key==='jurisdiction'){if(!o.name||o.name===o.previousJurisdiction||/^Option \d+$/.test(o.name)||jurisdictions.includes(o.name))o.name=el.value;o.previousJurisdiction=el.value;}if(el.dataset.key==='visaCount'){o.rows.forEach((r,j)=>{if(r.quantityType==='visaApplicants'){r.quantity=el.value;const input=document.querySelector('[data-option="'+el.dataset.option+'"][data-row="'+j+'"][data-key="quantity"]');if(input)input.value=el.value;}});}if(el.dataset.key==='quantity'&&target.quantityType==='visaApplicants'){o.visaCount=el.value;const count=document.querySelector('[data-option="'+el.dataset.option+'"][data-key="visaCount"]');if(count)count.value=el.value;}if(el.dataset.key==='optional'&&!target.optional)target.selected=false;if(el.dataset.key==='included'&&target.included){target.optional=false;target.selected=false;}if(el.dataset.key==='basis'){target.billing=target.basis;}changed();}});
